CREATE DATABASE IF NOT EXISTS atlas CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE atlas;
DROP TABLE IF EXISTS app_state;
DROP TABLE IF EXISTS app_users;
CREATE TABLE app_users (id VARCHAR(30) PRIMARY KEY, full_name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role ENUM('admin','artist','animator','editor','reviewer','project_manager','client','viewer') NOT NULL DEFAULT 'viewer', created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE app_state (id TINYINT PRIMARY KEY, state_json LONGTEXT NOT NULL, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
